import json,os
import numpy as np
FR=json.load(open('final_results.json'));QR=json.load(open('quintic_results.json'));CV=json.load(open('cv_results.json'))
os.makedirs('models',exist_ok=True)
UNITS={'bias':'V/s','rest':'V/s','visc':'1/s','gain':'V/(s*U)','freq':'1/Y','fric':'V/s','velScale':'V','dampSlope':'1/Y','even':'V/s','linearRest':'V/(s*Y)','cubicRest':'V/(s*Y**3)','quadraticForce':'V/(s*Y**2)','quinticRest':'V/(s*Y**5)','staticForce':'V/s','gateSpeed':'V','expCap':'-','stickRate':'1/s','softWidth':'V/s'}
DEFS={'bias':'constant acceleration offset','rest':'amplitude of the odd sinusoidal restoring term','visc':'positive baseline velocity damping coefficient','gain':'linear input coefficient','freq':'inverse-state frequency inside sine and cosine','fric':'magnitude of saturating moving-velocity damping','velScale':'velocity width of the hyperbolic tangent transition','dampSlope':'state dependence of positive exponential velocity damping','even':'coefficient of the even cosine-minus-one restoring correction','linearRest':'linear restoring coefficient','cubicRest':'cubic softening coefficient','quadraticForce':'coefficient of the even quadratic force correction','quinticRest':'fifth-degree inward restoring coefficient','staticForce':'force threshold of the low-speed static branch','gateSpeed':'velocity width of the Gaussian low-speed gate'}
common_units='Units are not supplied. In this record, Y denotes the unknown unit of `y`, V the unknown unit of `x1`, U the unknown unit of `x2`, and s seconds; these are unit placeholders, not expression symbols. The numerical relation `dy = x1` is assumed from within-trajectory centered differences, implying compatible numerical scaling V = Y/s, not a known physical calibration. The expressions use only the logged states and input; the column `dx1` is not an argument.'
ref='References: the SciPy reference documentation for `scipy.optimize.least_squares` describes the trust-region reflective method; Steven H. Strogatz, Nonlinear Dynamics and Chaos, is a general oscillator reference. These bibliographic references are cited from memory; attempted web checking returned no usable content, so neither source was verified online in this round. Neither reference establishes the identity or physics of this undisclosed system.'
settings='Classical fourth-order Runge-Kutta with `T_s = 0.01` s and `x2` held at the preceding logged sample is used, with measured initial states and no subsequent state replacement. Every trajectory is separate. SciPy `scipy.optimize.least_squares` uses trust-region reflective bounded nonlinear least squares, linear loss, two-point finite-difference Jacobians, Jacobian-based parameter scaling, `max_nfev = 350`, and `ftol = xtol = gtol = 1e-10`; the last four are dimensionless numerical settings. This method handles the small bounded nonlinear output-error problem directly; derivative least squares alone is insufficient because centered differentiated, quantized measurements need not be instantaneous acceleration. Numba only accelerates the deterministic RK4 calculations. No random numbers or seeds are used. '
criterion='Sum of squared free-run errors in `y` at every within-trajectory row after its initial sample, with equal weight per sample. This matches the scored output and long-run simulation requirement rather than optimizing the noisy centered derivative target. Errors have unit Y and the minimized sum has unit Y**2.'
data='Final coefficient estimation uses data/train.csv (all trajectories, all 3522 rows) and data/val.csv (all trajectories, all 1192 rows), with each initial row used solely to initialize simulation. No rows or trajectories are otherwise omitted. Structural screening first fits training data only and evaluates all validation trajectories without resetting the states; final refitting then uses both files to exploit all available experiments. Consequently final validation-file errors are in-sample, not new held-out evidence. The file names, sample counts and row roles are as supplied in TASK.md.'

def num(x):return format(float(x),'.16g')
def listed(values,names):return '; '.join('`'+n+' = '+num(values[i])+'`'+(' '+UNITS[n] if UNITS[n]!='-' else '') for i,n in names)
def params(r,names,active,static=False):
 rows=[]
 for i,n in names:
  fitted=i in active
  desc='`'+n+'` is the '+DEFS[n]+'. '
  if fitted:desc+='Estimated jointly in the final free-run output-error fit on both supplied files, from the training-only starting value reported in estimation.'
  else:desc+='Fixed at `velScale = 0.2` V in the final fit. This is a manually chosen smoothing hyperparameter, not a continuously optimized final coefficient: sensitivity fits on all training trajectories tested `velScale = 0.09`, `velScale = 0.12`, `velScale = 0.2` and `velScale = 0.4` V and compared their held-out validation simulations. The choice balances validation performance with resolution of the damping transition at `T_s = 0.01` s; its precise value is not identified physically.'
  rows.append(dict(name=n,value=r['p'][i],unit=UNITS[n],type='fitted' if fitted else 'fixed',description=desc))
 rows.append(dict(name='expCap',value=40.,unit='-',type='fixed',description='`expCap = 40` is a chosen dimensionless numerical safety cap for the exponential argument. It prevents overflow far beyond observed states; it is inactive over all fitted and screened trajectories. It is not inferred physical saturation.'))
 if static:
  rows.extend([dict(name='stickRate',value=100.,unit='1/s',type='fixed',description='`stickRate = 100` 1/s is the chosen low-speed velocity decay rate, equal to the inverse of the supplied `T_s = 0.01` s. This regularizes zero-speed sticking without discontinuous sign switching and gives a decay scale of one sample; it is not fitted.'),dict(name='softWidth',value=.1,unit='V/s',type='fixed',description='`softWidth = 0.1` V/s is a chosen acceleration smoothing width for the static-force dead zone. It is small relative to acceleration fluctuations in data/train.csv, and avoids non-differentiability of an exact positive-part operator. It is not fitted or an independently observed physical constant.')])
 return rows

def method(r,names,extra):
 active=r['active'];fitted=[(i,n) for i,n in names if i in active]
 bounds=r['bounds'];btext='; '.join('`'+num(bounds[0][i])+' <= '+n+' <= '+num(bounds[1][i])+'` '+UNITS[n] for i,n in fitted)
 return settings+'All fitted parameters listed in this candidate are re-estimated together in one final step on both files. They start from this family\'s preceding training-only simulation least-squares fit, whose numerical values are: '+listed(r['train_p'],fitted)+'. These warm starts were chosen because the preliminary fit already tracked the measured trajectories. The final optimization bounds are '+btext+'. Bounds keep damping positive, constrain plausible local restoring and forcing magnitudes, and avoid unresolved velocity transitions; they are search restrictions, not established physical limits. '+extra+' The earlier training-only search and its initial values are reproducible in the scripts stated in origin. `reproduce_candidates.py` reproduces the final joint step from the exact numerical training-fit starting values. '+ref

DAMP='visc*exp(Min(Max(-dampSlope*y, -expCap), expCap))*x1'
TRFORCE='bias - rest*sin(freq*y) + even*(cos(freq*y) - 1) + gain*x2'
TRACC=TRFORCE+' - '+DAMP+' - fric*tanh(x1/velScale)'
TRN=[(0,'bias'),(1,'rest'),(2,'visc'),(3,'gain'),(4,'freq'),(5,'fric'),(6,'velScale'),(7,'dampSlope'),(8,'even')]
QN=[(0,'bias'),(1,'linearRest'),(2,'visc'),(3,'gain'),(4,'cubicRest'),(5,'fric'),(6,'velScale'),(7,'dampSlope'),(8,'quadraticForce'),(9,'quinticRest')]
QACC='bias - linearRest*y + quadraticForce*y**2 + cubicRest*y**3 - quinticRest*y**5 - '+DAMP+' + gain*x2 - fric*tanh(x1/velScale)'
SN=TRN+[(9,'staticForce'),(10,'gateSpeed')]
gate='exp(-(x1/gateSpeed)**2)'
static='(('+TRFORCE+') - staticForce + sqrt((('+TRFORCE+') - staticForce)**2 + softWidth**2))/2 - (-('+TRFORCE+') - staticForce + sqrt((-('+TRFORCE+') - staticForce)**2 + softWidth**2))/2 - stickRate*x1'
SACC='(1 - '+gate+')*('+TRACC+') + '+gate+'*('+static+')'

base_lim=common_units+' Physical identity, calibrated units, independent measurement noise, hidden actuator dynamics and friction memory are unknown. The derivative columns are centered finite differences, not independent acceleration measurements. Training coverage is approximately `-2.514 <= y <= 2.536` Y, `-20.107 <= x1 <= 14.452` V and `-4.946 <= x2 <= 3.954` U, computed from data/train.csv and rounded outward. There is no guarantee outside this support or beyond the supplied trajectory durations. In particular, the asserted kinematic equation does not resolve quantization or initial-velocity error. '
records=[
 ('TrigDamping',FR['trig_exponential'],TRN,TRACC,False,
  'Continuous-time, forced second-order trigonometric oscillator with smooth Coulomb-like damping, an even trigonometric force correction and positive exponential state-dependent viscous damping. This is a phenomenological family, not identification of a pendulum apparatus. '+ref,
  common_units+' `dy = x1` supplies kinematic motion. In `'+TRACC+'`, `bias` supplies a constant offset, `-rest*sin(freq*y)` supplies odd locally restoring acceleration, `even*(cos(freq*y) - 1)` supplies an even state-dependent correction with zero value at the origin, and `gain*x2` supplies linear forcing. `-'+DAMP+'` opposes velocity with a positive state-dependent coefficient; `-fric*tanh(x1/velScale)` is odd saturating velocity damping, with smooth behavior near zero. `expCap` caps the exponential argument for numerical safety. No material or force units are asserted.',
  'PLAN.md lists the families before fitting. Kinematics came from centered-difference inspection in inspect_data.py. Affine, cubic and sine restoring candidates were tried in fit_models.py; sine or cubic restoring improved free-run error over affine dynamics. The helper derivative regression and residuals.py showed antisymmetric velocity residuals, motivating saturation via `tanh`. The training-only one-term forward screening in search_terms.py tested quadratic state, state-velocity, input-state and nonlinear input terms; `y*x1` and an even state force improved simulation residuals. Their operators are empirical choices, not physical deductions. In fit_final.py, `-visc*exp(-dampSlope*y)*x1` replaced affine state-dependent damping to preserve its sign on extrapolation; `even*(cos(freq*y) - 1)` is a bounded even correction instead of unbounded quadratic forcing. Values were subsequently jointly refitted; this structure did not come from automated genetic-programming symbolic regression.',
  base_lim+' Sinusoidal restoring is only locally restoring and introduces periodic equilibria not verified by the experiments. Exponential damping and the even force correction are empirical and correlated with velocity damping; the saturation law gives slow creep rather than exact static friction. The cap is inactive locally but arbitrary on extreme extrapolation.',
  'The final-step fixed velocity smoothing width was selected by the stated sensitivity sweep, not re-estimated. Its uncertainty is not included in the objective.'),
 ('QuinticDamping',QR,QN,QACC,False,
  'Continuous-time generalized Duffing-type polynomial oscillator, with restoring acceleration through degree five and smooth velocity damping. The fifth-degree inward term extends a cubic softening oscillator rather than assuming an exact spring law. '+ref,
  common_units+' In `'+QACC+'`, `bias` gives constant acceleration, `-linearRest*y` gives locally inward linear restoring acceleration, `quadraticForce*y**2` gives an even state asymmetry, `cubicRest*y**3` softens the linear restoring action, and `-quinticRest*y**5` gives an inward high-amplitude correction because its fitted coefficient is positive. `-'+DAMP+'` is positive state-dependent velocity damping, `gain*x2` is input forcing, and `-fric*tanh(x1/velScale)` is smooth saturating velocity damping. All force descriptions are mathematical effects, not known device physics; `dy = x1` is the assumed kinematic equation.',
  'After the prefit PLAN.md, fit_models.py compared affine and cubic acceleration with trigonometric alternatives. Its velocity residuals motivated the hyperbolic tangent term. The one-term output-error screen in search_terms.py supported `y*x1` and `y**2` corrections. fit_final.py used positive exponential damping instead of the affine state-velocity damping, and fitted an even quadratic force. The positive cubic-only acceleration becomes outward beyond its fitted local range; therefore fit_quintic.py tested the additional guessed stabilizing term `-quinticRest*y**5`, fitting its magnitude with a positive bound. It slightly improved held-out validation and gives inward acceleration at sufficiently large state magnitudes. This is an empirically fitted polynomial family, not a polynomial expansion asserted to be exact physics.',
  base_lim+' Degree-five coefficients are correlated because the large-amplitude support is short. Positive highest-degree inward acceleration does not guarantee one-step RK4 stability on large extrapolations; it can be stiff and the polynomial can have additional equilibria outside the observed range. No energy, symmetry or parameter interpretation beyond mathematical term effects is established. Saturating damping is smooth and does not create exact sticking.',
  'The fifth-degree coefficient starts from a training-only fit obtained by adding `quinticRest = 0.5` V/(s*Y**5) to the preliminary cubic model. It is estimated, not fixed. The final smoothing width remains a manually selected fixed hyperparameter.'),
 ('StaticBlend',FR['static_blend'],SN,SACC,True,
  'Continuous-time smooth blended static/moving-friction oscillator: a trigonometric force and moving-velocity damping are joined to a low-speed dead-zone acceleration branch by a Gaussian velocity gate. This is a smooth phenomenological stick/slip approximation, not a hidden friction-state model. '+ref,
  common_units+' The complete acceleration is `'+SACC+'`. Here `'+TRFORCE+'` is the net state/input force before damping, with constant, odd, even and input effects as their parameter descriptions define. `'+gate+'` tends to one near zero velocity and zero away from zero; it blends branches rather than switching discontinuously. The moving branch is `'+TRACC+'`. In the static branch, the two square-root positive-part approximations implement a smooth force dead zone of threshold `staticForce`; `softWidth` smooths its corners. `-stickRate*x1` rapidly decays low velocity. `gateSpeed` sets the near-zero-velocity band, not an extra state. `velScale` is the separately fitted moving-damping width. The model may reduce low-force creep but is not exact sticking because its smoothing is finite. `dy = x1` remains the kinematic equation.',
  'Centered-difference inspection motivated kinematics, and residuals.py showed measured low-speed plateaus at different state values: smooth moving friction alone allowed unwanted creep. fit_extended.py therefore compared a smooth force dead zone, a Gaussian static/moving blend, Stribeck damping, asymmetric friction and a discontinuous low-speed model. The Gaussian blend was retained as a distinct, continuously evaluable family; its gate and regularizing low-speed decay are guessed approximations motivated by plateau residuals, not observed physical states. fit_final.py added the empirically supported even trigonometric force and positive exponential damping and jointly estimated the model. The static branch was not produced by symbolic-regression software. More complex harmonic and nonlinear-input models did not justify inclusion in this pool.',
  base_lim+' Static threshold, gate width and moving-friction smoothing are partly interchangeable; there are no independent friction or force measurements. The narrow fitted Gaussian gate may be weakly resolved by sampling, and different starts gave modestly different low-speed parameter values. One grouped cross-validation fold reached its allowed function-evaluation count, so superiority over the simpler model is not claimed. True hysteretic friction needs an additional memory state which this two-state model cannot contain. Fixed low-speed decay and square-root smoothing are numerical modeling assumptions.',
  'All moving width, static threshold and gate-width parameters are fitted in this candidate. The static smoothing and low-speed decay are fixed regularization assumptions, not estimated coefficients.')]

for label,r,names,expression,static,family,interp,origin,limits,extra in records:
 active=r['active'];doc={'expressions':{'dy':'x1','dx1':expression},'parameters':params(r,names,active,static),'estimation':{'criterion':criterion,'data':data,'method':method(r,names,extra),'script':'reproduce_candidates.py'},'discussion':{'family':family,'interpretation':interp,'origin':origin,'limitations':limits}}
 json.dump(doc,open('models/'+label+'.json','w'),indent=2)
reason='Recommend QuinticDamping: its training-only fit gave validation RMSE 0.0712333 Y and four-fold trajectory-grouped diagnostic RMSE 0.0543695 Y, compared with 0.0728230 Y / 0.0557991 Y for TrigDamping and 0.0759100 Y / 0.0557450 Y for StaticBlend. Y is the unknown output unit. These small differences are not statistically decisive; it is recommended for its consistent held-trajectory output accuracy, not a proven physical spring interpretation. All three delivered candidates were subsequently refitted on both supplied files, so their final validation-file errors are in-sample. Grouped diagnostics use the final coefficients as numerical warm starts and reuse structure/smoothing choices screened on these files; they are not a completely untouched assessment. Quintic extrapolation can be stiff and have extra equilibria; the trigonometric model is the simpler bounded-force alternative.'
json.dump({'order':['QuinticDamping','TrigDamping','StaticBlend'],'recommended':'QuinticDamping','reason':reason},open('models/pool.json','w'),indent=2)
print('Wrote three candidate files and pool.')
